(2229989, 306849, 10848, '<td valign="top">Nice, very nostalgic.</td>', 'Nice, very nostalgic.', '2006-03-15 10:11:52.000000', NULL, 1),
(2229994, 306713, 5792, '<td valign="top">The arrangement and composition of this image is fine.<br/> <br/>Lighting and color could be improved. The shadow of the calculator distracts from the image. Adding lighting from the right would mute the distaction, illuminate right side detail and add interest to the image.<br/> <br/>White balance is off which gives it a yellow hue that should be corrected in post processing.<br/> <br/>You might also consider shifting your central focus point from the center of the calculator to the "5" on the keypad. That would excentuate the effect of your shallow depth of field and minimize the distracting effect of having the near foreground slightly out of focus.</td>', 'The arrangement and composition of this image is fine. Lighting and color could be improved. The shadow of the calculator distracts from the image. Adding lighting from the right would mute the distaction, illuminate right side detail and add interest to the image. White balance is off which gives it a yellow hue that should be corrected in post processing. You might also consider shifting your central focus point from the center of the calculator to the "5" on the keypad. That would excentuate the effect of your shallow depth of field and minimize the distracting effect of having the near foreground slightly out of focus.', '2006-03-15 10:13:04.000000', NULL, 1),
(2229996, 306836, 10848, '<td valign="top">LOL! Now this is funny. Very creative and a wonderful capture. If humor plays a part in the ribbon you got it hands down! Good luck!</td>', 'LOL! Now this is funny. Very creative and a wonderful capture. If humor plays a part in the ribbon you got it hands down! Good luck!', '2006-03-15 10:13:19.000000', NULL, 1),
