(2230723, 306488, 42495, '<td valign="top">I was going to do this exact same thing but ran out of time...</td>', 'I was going to do this exact same thing but ran out of time...', '2006-03-15 13:44:55.000000', NULL, 1),
(2230724, 306439, 16402, '<td valign="top">Good job. Lighting and props all work together to support the title and concept.</td>', 'Good job. Lighting and props all work together to support the title and concept.', '2006-03-15 13:45:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2230729, 304925, 16402, '<td valign="top">Well exposed documentary type shot, but not much "wow" factor here. Maybe one student at a locker or walking the hall would have added to it.</td>', 'Well exposed documentary type shot, but not much "wow" factor here. Maybe one student at a locker or walking the hall would have added to it.', '2006-03-15 13:47:01.000000', NULL, 1),
(2230732, 306624, 16402, '<td valign="top">Nice sharp focus with very documentary feel and even a bit motion.</td>', 'Nice sharp focus with very documentary feel and even a bit motion.', '2006-03-15 13:48:19.000000', NULL, 1),
(2230733, 306246, 44490, '<td valign="top">Nice idea, but even purposeful camera shake blur doesn''t work.  Something in your image should be sharp.  Alternatives would be camera flash (sharp) combined with camera movement (blur), or a filter with vaseline, etc.</td>', 'Nice idea, but even purposeful camera shake blur doesn''t work.  Something in your image should be sharp.  Alternatives would be camera flash (sharp) combined with camera movement (blur), or a filter with vaseline, etc.', '2006-03-15 13:49:15.000000', NULL, 1),
(2230734, 306447, 43936, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2006-03-15 13:49:53.000000', NULL, 1),
(2230739, 306938, 16402, '<td valign="top">Cute shot to illustrate the theme. Very well exposed and executed.</td>', 'Cute shot to illustrate the theme. Very well exposed and executed.', '2006-03-15 13:50:18.000000', NULL, 1),
(2230741, 306468, 42495, '<td valign="top">Nice picture but a bit too small.</td>', 'Nice picture but a bit too small.', '2006-03-15 13:50:40.000000', NULL, 1),
(2230744, 306193, 16402, '<td valign="top">Meets the challenge but lacks something to make it pop, but I can''t put my finger on what that is.</td>', 'Meets the challenge but lacks something to make it pop, but I can''t put my finger on what that is.', '2006-03-15 13:51:32.000000', NULL, 1),
(2230747, 306708, 16402, '<td valign="top">Exposure on this is not too bad and composition is even OK but focus is off.</td>', 'Exposure on this is not too bad and composition is even OK but focus is off.', '2006-03-15 13:52:25.000000', NULL, 1),
(2230748, 306417, 16402, '<td valign="top">Simple with nice DOF and color.</td>', 'Simple with nice DOF and color.', '2006-03-15 13:52:56.000000', NULL, 1),
(2230749, 306108, 42495, '<td valign="top">Didn''t somebody say to just get a bigger hammer? Thanks for the laugh.</td>', 'Didn''t somebody say to just get a bigger hammer? Thanks for the laugh.', '2006-03-15 13:52:59.000000', NULL, 1),
(2230756, 306849, 16402, '<td valign="top">Technically, this shot is very good: Nice and sharp, good composition and color, but to me it lacks the human element that accompanies the idea of education. It almost has a vacation shot feel to me. Maybe including a person in the photo would have helped.</td>', 'Technically, this shot is very good: Nice and sharp, good composition and color, but to me it lacks the human element that accompanies the idea of education. It almost has a vacation shot feel to me. Maybe including a person in the photo would have helped.', '2006-03-15 13:56:07.000000', NULL, 1),
(2230760, 306513, 16402, '<td valign="top">Excellent! Excellent concept, excellent lighting, excellent composition. Highest score from me so far: 9 and may bump it later.</td>', 'Excellent! Excellent concept, excellent lighting, excellent composition. Highest score from me so far: 9 and may bump it later.', '2006-03-15 13:58:42.000000', NULL, 1),
(2230764, 304751, 16402, '<td valign="top">Really pretty nice. Like the stair-step of the books with bulb. Exposure and composition are both good.</td>', 'Really pretty nice. Like the stair-step of the books with bulb. Exposure and composition are both good.', '2006-03-15 14:00:40.000000', NULL, 1),
(2230777, 306822, 44490, '<td valign="top">Nice pose, and oversized jacket is too cute.  Unfortunately looks like backfocus, sharper focus on subject and less dead-center composition would be better.</td>', 'Nice pose, and oversized jacket is too cute.  Unfortunately looks like backfocus, sharper focus on subject and less dead-center composition would be better.', '2006-03-15 14:05:13.000000', NULL, 1),
(2230793, 306708, 42495, '<td valign="top">Is this out of focus on purpose?</td>', 'Is this out of focus on purpose?', '2006-03-15 14:11:36.000000', NULL, 1),
(2230795, 306777, 16402, '<td valign="top">Colorful but not compelling.</td>', 'Colorful but not compelling.', '2006-03-15 14:12:36.000000', NULL, 1),
(2230797, 306665, 16402, '<td valign="top">Cute animals photos with "education" titles not getting my votes today, sorry.</td>', 'Cute animals photos with "education" titles not getting my votes today, sorry.', '2006-03-15 14:13:11.000000', NULL, 1),
(2230802, 306176, 16402, '<td valign="top">Very nicely done documentary type shot. Sharp with excellent exposure just missing the human element of education. I could see this on the school district''s web site or a brochure for the school, though.</td>', 'Very nicely done documentary type shot. Sharp with excellent exposure just missing the human element of education. I could see this on the school district''s web site or a brochure for the school, though.', '2006-03-15 14:14:47.000000', NULL, 1),
(2230809, 305114, 44490, '<td valign="top">Nice idea.  The book chops through the composition.  Maybe angling the book downward would allow you to reduce its dominance?</td>', 'Nice idea.  The book chops through the composition.  Maybe angling the book downward would allow you to reduce its dominance?', '2006-03-15 14:15:52.000000', NULL, 1),
(2230810, 305674, 16402, '<td valign="top">Good job with the exposure (snow can be tricky) and composition is pretty good too. A bit too documentary though for my taste and lacking the human element of education.</td>', 'Good job with the exposure (snow can be tricky) and composition is pretty good too. A bit too documentary though for my taste and lacking the human element of education.', '2006-03-15 14:15:59.000000', NULL, 1),
(2230812, 305397, 16402, '<td valign="top">Underexposed and no really very original, although it certainly does convey the idea of "education."</td>', 'Underexposed and no really very original, although it certainly does convey the idea of "education."', '2006-03-15 14:16:47.000000', NULL, 1),
(2230815, 306757, 16402, '<td valign="top">Just a very cute shot. Pretty well exposed but may a bit soft on focus.</td>', 'Just a very cute shot. Pretty well exposed but may a bit soft on focus.', '2006-03-15 14:17:39.000000', NULL, 1),
(2230821, 306444, 16402, '<td valign="top">Pretty nice. Composition is OK but the exposure on the metal is great.</td>', 'Pretty nice. Composition is OK but the exposure on the metal is great.', '2006-03-15 14:18:42.000000', NULL, 1),
(2230824, 306444, 44490, '<td valign="top">Nice composition.  Brighter levels would help, as the overall image feels gray.</td>', 'Nice composition.  Brighter levels would help, as the overall image feels gray.', '2006-03-15 14:19:19.000000', NULL, 1),
(2230826, 306926, 16402, '<td valign="top">Very interesting and clever still life. Highlights a tiny bit blown out at bottom of pencils and reflections a bit much on the apple, but still a good job.</td>', 'Very interesting and clever still life. Highlights a tiny bit blown out at bottom of pencils and reflections a bit much on the apple, but still a good job.', '2006-03-15 14:19:47.000000', NULL, 1),
(2230828, 304941, 16402, '<td valign="top">Just enough kinkiness behind this photo to get an extra point or two from me.</td>', 'Just enough kinkiness behind this photo to get an extra point or two from me.', '2006-03-15 14:21:07.000000', NULL, 1),
(2230833, 306217, 16402, '<td valign="top">Very nice documentary style shot. Great exposure and interesting subject, plus some motion. Very nice job.</td>', 'Very nice documentary style shot. Great exposure and interesting subject, plus some motion. Very nice job.', '2006-03-15 14:22:56.000000', NULL, 1),
(2230835, 306492, 16402, '<td valign="top">Very nice job on the pencil motion and her expression. Not sure the softness really works for me, but it still a very nice "education" shot.</td>', 'Very nice job on the pencil motion and her expression. Not sure the softness really works for me, but it still a very nice "education" shot.', '2006-03-15 14:23:53.000000', NULL, 1),
(2230837, 306861, 16402, '<td valign="top">Concept and compositon a little too simple for me but exposure and focus are great.</td>', 'Concept and compositon a little too simple for me but exposure and focus are great.', '2006-03-15 14:24:43.000000', NULL, 1),
(2230843, 306644, 16402, '<td valign="top">Seems just a bit too far left in frame for me, but exposure and focus are pretty good.</td>', 'Seems just a bit too far left in frame for me, but exposure and focus are pretty good.', '2006-03-15 14:25:25.000000', NULL, 1),
(2230844, 306853, 44490, '<td valign="top">Nice composition.  How about a title like "Formula for Learning" or "Modern Alchemy?"</td>', 'Nice composition.  How about a title like "Formula for Learning" or "Modern Alchemy?"', '2006-03-15 14:25:52.000000', NULL, 1),
(2230845, 306699, 16402, '<td valign="top">Incredible DOF but otherwise composition doesn''t excite me.</td>', 'Incredible DOF but otherwise composition doesn''t excite me.', '2006-03-15 14:26:06.000000', NULL, 1),
(2230847, 306279, 16402, '<td valign="top">Seems a bit underexposed and out of focus to me.</td>', 'Seems a bit underexposed and out of focus to me.', '2006-03-15 14:26:30.000000', NULL, 1),
(2230852, 306924, 16402, '<td valign="top">I really like this image but not for this challenge. Exposure is very good as is focus but it doesn''t say "education" to me and the selective color seems gimmicky.</td>', 'I really like this image but not for this challenge. Exposure is very good as is focus but it doesn''t say "education" to me and the selective color seems gimmicky.', '2006-03-15 14:27:59.000000', NULL, 1),
(2230855, 306439, 41051, '<td valign="top">Good one.</td>', 'Good one.', '2006-03-15 14:28:22.000000', NULL, 1),
(2230859, 305588, 16402, '<td valign="top">Exposure is pretty good considering mid-day sun but composition includes way too much sky that doesn''t add to the theme of "education." Think might have had a better shot by getting closer and eliminating so much of the sky.</td>', 'Exposure is pretty good considering mid-day sun but composition includes way too much sky that doesn''t add to the theme of "education." Think might have had a better shot by getting closer and eliminating so much of the sky.', '2006-03-15 14:29:55.000000', NULL, 1),
(2230860, 306943, 54832, '<td valign="top">A little dark for my taste.</td>', 'A little dark for my taste.', '2006-03-15 14:29:57.000000', NULL, 1),
(2230862, 305679, 16402, '<td valign="top">Very striking composition although very documentary-like. Seems just a bit overexposed.</td>', 'Very striking composition although very documentary-like. Seems just a bit overexposed.', '2006-03-15 14:30:59.000000', NULL, 1),
(2230863, 306488, 54832, '<td valign="top">Cute kid.</td>', 'Cute kid.', '2006-03-15 14:31:05.000000', NULL, 1),
(2230865, 306108, 51003, '<td valign="top">Can we do this type of editing for this challenge?</td>', 'Can we do this type of editing for this challenge?', '2006-03-15 14:31:39.000000', NULL, 1),
(2230868, 305883, 16402, '<td valign="top">Very nice shot. Good highlight and shadow detail and geometrics of the chairs on the desks adds a cool element to composition.</td>', 'Very nice shot. Good highlight and shadow detail and geometrics of the chairs on the desks adds a cool element to composition.', '2006-03-15 14:32:05.000000', NULL, 1),
(2230873, 304603, 16402, '<td valign="top">Too low key for me.</td>', 'Too low key for me.', '2006-03-15 14:32:46.000000', NULL, 1),
(2230879, 306853, 16402, '<td valign="top">Exposure''s not to bad, maybe a bit low-key but composition is way to busy. I don''t know where to look first or linger, sorry</td>', 'Exposure''s not to bad, maybe a bit low-key but composition is way to busy. I don''t know where to look first or linger, sorry', '2006-03-15 14:34:01.000000', NULL, 1),
(2230891, 306570, 44490, '<td valign="top">Nice composition and poses, stacks and stained glass windows.  Some areas are blown out, and the image looks overprocessed with grain from oversharpening.</td>', 'Nice composition and poses, stacks and stained glass windows.  Some areas are blown out, and the image looks overprocessed with grain from oversharpening.', '2006-03-15 14:37:09.000000', NULL, 1),
(2230893, 306842, 39686, '<td valign="top">I love the colours!</td>', 'I love the colours!', '2006-03-15 14:38:09.000000', NULL, 1),
(2230896, 306926, 39686, '<td valign="top">Love the blue one very much :D</td>', 'Love the blue one very much :D', '2006-03-15 14:39:05.000000', NULL, 1),
(2230903, 306755, 44490, '<td valign="top">Nice candid appearance.  Crop out top and bottom some would be better, and allow image to be larger so that the NASA t-shirt is more obvious, as I missed it on the first viewing.</td>', 'Nice candid appearance.  Crop out top and bottom some would be better, and allow image to be larger so that the NASA t-shirt is more obvious, as I missed it on the first viewing.', '2006-03-15 14:42:14.000000', NULL, 1),
(2230904, 306489, 16402, '<td valign="top">Very nice! Focus is spectacular, high-key exposure works for me this time and composition is good.</td>', 'Very nice! Focus is spectacular, high-key exposure works for me this time and composition is good.', '2006-03-15 14:42:17.000000', NULL, 1),
(2230910, 306281, 16402, '<td valign="top">Image has a really nice mood to it with soft lighting and focus. I don''t even mind the selective color too much in this one, although I''d have to compare it to all black and white.</td>', 'Image has a really nice mood to it with soft lighting and focus. I don''t even mind the selective color too much in this one, although I''d have to compare it to all black and white.', '2006-03-15 14:44:24.000000', NULL, 1),
(2230912, 306492, 44490, '<td valign="top">Nice pose, composition, and lighting.  Wish for some eye(ball)s, i.e., looking at camera with an interesting expression would be best, but I''d settle for more visible eyes not looking at the camera, especially for a posed shot.</td>', 'Nice pose, composition, and lighting.  Wish for some eye(ball)s, i.e., looking at camera with an interesting expression would be best, but I''d settle for more visible eyes not looking at the camera, especially for a posed shot.', '2006-03-15 14:45:39.000000', NULL, 1),
(2230913, 306759, 16402, '<td valign="top">Exposure and focus on this are both very good but concept doesn''t work for me. I don''t know if you worked too hard on this idea or not hard enough but I don''t find it satisfying.</td>', 'Exposure and focus on this are both very good but concept doesn''t work for me. I don''t know if you worked too hard on this idea or not hard enough but I don''t find it satisfying.', '2006-03-15 14:45:44.000000', NULL, 1),
(2230918, 306584, 16402, '<td valign="top">This is a nice image, although the highlights seem a bit blown out, but my main problem with it is that it doesn''t say "education" to me. Maybe it''s a cultural thing.</td>', 'This is a nice image, although the highlights seem a bit blown out, but my main problem with it is that it doesn''t say "education" to me. Maybe it''s a cultural thing.', '2006-03-15 14:47:02.000000', NULL, 1),
(2230920, 304941, 44490, '<td valign="top">Nice composition, colors, hair ribbons.  Given the pose, the apple becomes a major element, so DOF to include it would be better.</td>', 'Nice composition, colors, hair ribbons.  Given the pose, the apple becomes a major element, so DOF to include it would be better.', '2006-03-15 14:47:45.000000', NULL, 1),
(2230925, 306185, 44490, '<td valign="top">Nice composition.  Somehow seems like backfocus, sharper faces would be better, and I wish for an eye or two.</td>', 'Nice composition.  Somehow seems like backfocus, sharper faces would be better, and I wish for an eye or two.', '2006-03-15 14:49:30.000000', NULL, 1),
(2230927, 306132, 44490, '<td valign="top">Interesting idea.  Cropped stop sign cuts the composition in two.  Would be better if you backed up to avoid this, and the more obvious stop sign would help many other viewers "get it."</td>', 'Interesting idea.  Cropped stop sign cuts the composition in two.  Would be better if you backed up to avoid this, and the more obvious stop sign would help many other viewers "get it."', '2006-03-15 14:49:43.000000', NULL, 1),
(2230929, 306757, 44490, '<td valign="top">Delightful expressions, nice colors, pretty good composition, and backlit hat is nice.  A bit sharper and with all of the feet would be better.</td>', 'Delightful expressions, nice colors, pretty good composition, and backlit hat is nice.  A bit sharper and with all of the feet would be better.', '2006-03-15 14:50:17.000000', NULL, 1),
(2230931, 306938, 44490, '<td valign="top">Cute compostion and subject.  Sharper focus and a little more illumination on face would be better.</td>', 'Cute compostion and subject.  Sharper focus and a little more illumination on face would be better.', '2006-03-15 14:50:34.000000', NULL, 1),
(2230932, 306671, 44490, '<td valign="top">Nice idea. There''s too much out of focus foreground, cropping to about 2/3 upper left would be better.</td>', 'Nice idea. There''s too much out of focus foreground, cropping to about 2/3 upper left would be better.', '2006-03-15 14:50:56.000000', NULL, 1),
(2230935, 304580, 44490, '<td valign="top">Great idea.  A little more illumination would help.</td>', 'Great idea.  A little more illumination would help.', '2006-03-15 14:52:17.000000', NULL, 1),
(2230937, 306461, 44490, '<td valign="top">Nice composition, interesting architecture, and subject in motion.  The duotone choice sems to have resulted in too much of one color.  A slight contrast bump might help to reduce this feel.</td>', 'Nice composition, interesting architecture, and subject in motion.  The duotone choice sems to have resulted in too much of one color.  A slight contrast bump might help to reduce this feel.', '2006-03-15 14:52:30.000000', NULL, 1),
(2230938, 305674, 44490, '<td valign="top">Nice composition and colors.  Would be better with slight angle fix and less (over)sharpening.</td>', 'Nice composition and colors.  Would be better with slight angle fix and less (over)sharpening.', '2006-03-15 14:52:35.000000', NULL, 1),
(2230944, 306176, 44490, '<td valign="top">Nice composition, architecture, beautiful entrance, especially with the illumination.  Wish for a student to complete the image to make it less sterile.</td>', 'Nice composition, architecture, beautiful entrance, especially with the illumination.  Wish for a student to complete the image to make it less sterile.', '2006-03-15 14:55:22.000000', NULL, 1),
(2230954, 306926, 40344, '<td valign="top">Clever idea, nicely done.</td>', 'Clever idea, nicely done.', '2006-03-15 14:57:15.000000', NULL, 1),
(2230971, 304513, 54832, '<td valign="top">I don''t see the connection.</td>', 'I don''t see the connection.', '2006-03-15 15:02:35.000000', NULL, 1),
(2230975, 306281, 44490, '<td valign="top">Nice composition, color, soft feel of the snow.</td>', 'Nice composition, color, soft feel of the snow.', '2006-03-15 15:03:23.000000', NULL, 1),
(2230982, 306936, 16402, '<td valign="top">Concept is pretty thing for "education" and exposure is a bit too much.</td>', 'Concept is pretty thing for "education" and exposure is a bit too much.', '2006-03-15 15:06:14.000000', NULL, 1),
(2230983, 305617, 16402, '<td valign="top">Seems just a tiny bit underexposed, but I like frames filled with repetition of times so this works pretty good for me.</td>', 'Seems just a tiny bit underexposed, but I like frames filled with repetition of times so this works pretty good for me.', '2006-03-15 15:07:30.000000', NULL, 1),
(2230985, 306753, 16402, '<td valign="top">Sorry just don''t get the "education" connection.</td>', 'Sorry just don''t get the "education" connection.', '2006-03-15 15:08:02.000000', NULL, 1),
(2230987, 306534, 16402, '<td valign="top">You stretch the concept too far from the theme for me, sorry. But technically it''s a nice shot.</td>', 'You stretch the concept too far from the theme for me, sorry. But technically it''s a nice shot.', '2006-03-15 15:08:47.000000', NULL, 1),
(2230992, 306226, 16402, '<td valign="top">Simple with good exposure and focus, plus OK composition.</td>', 'Simple with good exposure and focus, plus OK composition.', '2006-03-15 15:09:48.000000', NULL, 1),
(2230993, 306437, 54832, '<td valign="top">I know that look!  Nice!</td>', 'I know that look!  Nice!', '2006-03-15 15:10:03.000000', NULL, 1),
(2230995, 306554, 16402, '<td valign="top">I don''t really go for cute animal photos but yours is technically good and at least you tried to make the image, not just the title, match the theme.</td>', 'I don''t really go for cute animal photos but yours is technically good and at least you tried to make the image, not just the title, match the theme.', '2006-03-15 15:10:53.000000', NULL, 1),
(2230999, 306755, 16402, '<td valign="top">Nice natural light portrait. I''d have cropped it tighter at top and bottom.</td>', 'Nice natural light portrait. I''d have cropped it tighter at top and bottom.', '2006-03-15 15:11:52.000000', NULL, 1),
(2231004, 305053, 16402, '<td valign="top">Wow, that''s really a stretch to meet the theme for me. Technically it''s a nice shot though.</td>', 'Wow, that''s really a stretch to meet the theme for me. Technically it''s a nice shot though.', '2006-03-15 15:12:42.000000', NULL, 1),
(2231007, 306311, 16402, '<td valign="top">I can tell they''re students so you met your theme requirement and it''s pretty good technically even it not that interesting.</td>', 'I can tell they''re students so you met your theme requirement and it''s pretty good technically even it not that interesting.', '2006-03-15 15:13:43.000000', NULL, 1),
(2231010, 306325, 16402, '<td valign="top">Very nice shot with excellent exposure, focus and compositon. One of my top picks.</td>', 'Very nice shot with excellent exposure, focus and compositon. One of my top picks.', '2006-03-15 15:16:41.000000', NULL, 1),
(2231013, 305508, 16402, '<td valign="top">Very nice shot. Well exposed, good focus (DOF) and satisfying composition.</td>', 'Very nice shot. Well exposed, good focus (DOF) and satisfying composition.', '2006-03-15 15:18:27.000000', NULL, 1),
(2231014, 306806, 44490, '<td valign="top">Liberty Science Center!  Nice capture, interesting viewing angle for interesting architecture.  Looks like you even caught an airplane above the dome.  Consider fixing the slight tilt to the left.</td>', 'Liberty Science Center!  Nice capture, interesting viewing angle for interesting architecture.  Looks like you even caught an airplane above the dome.  Consider fixing the slight tilt to the left.', '2006-03-15 15:19:06.000000', NULL, 1),
(2231015, 306934, 16402, '<td valign="top">While this is an interesting photo of an interesting looking person, it doesn''t say "education" to me all by itself.</td>', 'While this is an interesting photo of an interesting looking person, it doesn''t say "education" to me all by itself.', '2006-03-15 15:19:13.000000', NULL, 1),
(2231018, 304593, 44490, '<td valign="top">Great capture, composition, colors, poses.  Makes me smile.</td>', 'Great capture, composition, colors, poses.  Makes me smile.', '2006-03-15 15:20:08.000000', NULL, 1),
(2231019, 306269, 16402, '<td valign="top">Exposure seems uneven to me and it is way to busy. Doesn''t seem like much thought was put into composition.</td>', 'Exposure seems uneven to me and it is way to busy. Doesn''t seem like much thought was put into composition.', '2006-03-15 15:20:15.000000', NULL, 1),
(2231024, 306325, 44490, '<td valign="top">Striking composition, subject in red, "tree of knowledge..."  - very nice.</td>', 'Striking composition, subject in red, "tree of knowledge..."  - very nice.', '2006-03-15 15:21:44.000000', NULL, 1),
(2231026, 306132, 16402, '<td valign="top">Sorry, but this doesn''t meet the theme for me. Without the title there''s nothing about it that says "education" to me. Composition and exposure aren''t bad though.</td>', 'Sorry, but this doesn''t meet the theme for me. Without the title there''s nothing about it that says "education" to me. Composition and exposure aren''t bad though.', '2006-03-15 15:21:55.000000', NULL, 1),
(2231027, 306846, 44490, '<td valign="top">Nice composition, expressions, hands, body in motion - nicely done.</td>', 'Nice composition, expressions, hands, body in motion - nicely done.', '2006-03-15 15:22:33.000000', NULL, 1),
(2231028, 306374, 16402, '<td valign="top">Concept is not very original to me. Exposure seems a bit uneven and it also appears oversharpened.</td>', 'Concept is not very original to me. Exposure seems a bit uneven and it also appears oversharpened.', '2006-03-15 15:23:03.000000', NULL, 1),
(2231030, 306414, 44490, '<td valign="top">Nice composition, color, elements, mealworm, reflections, and processing of chalkboard.  Humorous, and could hardly be better.</td>', 'Nice composition, color, elements, mealworm, reflections, and processing of chalkboard.  Humorous, and could hardly be better.', '2006-03-15 15:23:04.000000', NULL, 1),
