(2233086, 306671, 16402, '<td valign="top">Fabulous use of DOF! Maybe a bit underexposed though.</td>', 'Fabulous use of DOF! Maybe a bit underexposed though.', '2006-03-16 10:14:50.000000', NULL, 1),
