(2233416, 305136, 44172, '<td valign="top">good idea, him in the thirds is great, top corners are a bit distracting, in my opinion - if it were only all purple seats and him - that would be best, certainly meets challenge - good job :)</td>', 'good idea, him in the thirds is great, top corners are a bit distracting, in my opinion - if it were only all purple seats and him - that would be best, certainly meets challenge - good job :)', '2006-03-16 12:16:50.000000', NULL, 1),
(2233420, 306513, 44172, '<td valign="top">very nice composition, like the sepia tone - certainly enhances what you are trying to do, not sure about the bottom left corner - a wee bit distracting, a good idea though and certainly meets challenge - good job :)</td>', 'very nice composition, like the sepia tone - certainly enhances what you are trying to do, not sure about the bottom left corner - a wee bit distracting, a good idea though and certainly meets challenge - good job :)', '2006-03-16 12:18:49.000000', NULL, 1),
(2233421, 304580, 53571, '<td valign="top">Very clever.One of my favorite 3 ideas this week.</td>', 'Very clever.One of my favorite 3 ideas this week.', '2006-03-16 12:18:58.000000', NULL, 1),
(2233422, 306671, 53571, '<td valign="top">Nice moment. Maybe a little grey.</td>', 'Nice moment. Maybe a little grey.', '2006-03-16 12:19:38.000000', NULL, 1),
(2233429, 306926, 53571, '<td valign="top">clever idea. I enjoy the attention to detail (Ribbon). Its a little washed out in the erasers.</td>', 'clever idea. I enjoy the attention to detail (Ribbon). Its a little washed out in the erasers.', '2006-03-16 12:20:23.000000', NULL, 1),
(2233430, 304593, 44172, '<td valign="top">one of my favorites in the lot, a very nice candid, their red uniforms work so well against the drab rainy day, which works very well for making the reflections on the sidewalk, very nice capture - good job :)</td>', 'one of my favorites in the lot, a very nice candid, their red uniforms work so well against the drab rainy day, which works very well for making the reflections on the sidewalk, very nice capture - good job :)', '2006-03-16 12:20:27.000000', NULL, 1),
