(2233438, 306801, 53571, '<td valign="top">Good idea. I might have composed the shot to hid the two lines near the lightbulb... add to the mystery.</td>', 'Good idea. I might have composed the shot to hid the two lines near the lightbulb... add to the mystery.', '2006-03-16 12:22:50.000000', NULL, 1),
(2233440, 305588, 44172, '<td valign="top">nice tone and crop - very simple image, not sure if without your title this would meet the challenge so well - but it''s a nice image none the less :)</td>', 'nice tone and crop - very simple image, not sure if without your title this would meet the challenge so well - but it''s a nice image none the less :)', '2006-03-16 12:22:58.000000', NULL, 1),
(2233441, 306700, 53571, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2006-03-16 12:23:01.000000', NULL, 1),
