(2233445, 306447, 53571, '<td valign="top">Nice perspective (vanishing point). good use of selective depth of field also.</td>', 'Nice perspective (vanishing point). good use of selective depth of field also.', '2006-03-16 12:24:00.000000', NULL, 1),
(2233449, 304967, 44172, '<td valign="top">LOL - nice macro and great idea - the attention you paid to the details are great, bite marks in the pencil, #71 being erased and changed, broken pencil - great execution of this - good job :)</td>', 'LOL - nice macro and great idea - the attention you paid to the details are great, bite marks in the pencil, #71 being erased and changed, broken pencil - great execution of this - good job :)', '2006-03-16 12:24:36.000000', NULL, 1),
(2233450, 306414, 53571, '<td valign="top">I love this idea. The reflection in the glasses is very cool. The worm is also a nice touch. There is something off with the colors to my eye. A little too saturated.  Nice job though.</td>', 'I love this idea. The reflection in the glasses is very cool. The worm is also a nice touch. There is something off with the colors to my eye. A little too saturated.  Nice job though.', '2006-03-16 12:24:40.000000', NULL, 1),
(2233451, 304616, 44172, '<td valign="top">very nice quality candid - black and white seems nice - would be interested to see it in color though too, certainly meets the challenge - good job :)</td>', 'very nice quality candid - black and white seems nice - would be interested to see it in color though too, certainly meets the challenge - good job :)', '2006-03-16 12:25:30.000000', NULL, 1),
(2233452, 304879, 53571, '<td valign="top">Simple, straight forward. A good literal interpretation of the challenge.</td>', 'Simple, straight forward. A good literal interpretation of the challenge.', '2006-03-16 12:25:30.000000', NULL, 1),
(2233454, 305284, 53571, '<td valign="top">I think I would like this better with more selective focus and a smaller depth of field.</td>', 'I think I would like this better with more selective focus and a smaller depth of field.', '2006-03-16 12:25:54.000000', NULL, 1),
(2233457, 304750, 53571, '<td valign="top">Very abstract. Interesting image. Difficult to relate to the challenge.</td>', 'Very abstract. Interesting image. Difficult to relate to the challenge.', '2006-03-16 12:26:13.000000', NULL, 1),
(2233461, 304779, 44172, '<td valign="top">nice job capturing their school days :)</td>', 'nice job capturing their school days :)', '2006-03-16 12:27:02.000000', NULL, 1),
(2233473, 305508, 44172, '<td valign="top">nice simple image, good quality, would have liked to see less crop on top allowing for some space above her head, certainly meets challenge - as it''s obvious she is studying - especially with your good title, nice job :)</td>', 'nice simple image, good quality, would have liked to see less crop on top allowing for some space above her head, certainly meets challenge - as it''s obvious she is studying - especially with your good title, nice job :)', '2006-03-16 12:35:01.000000', NULL, 1),
(2233476, 306865, 44172, '<td valign="top">awww..this screams "education" to me - great idea - and how lucky for you to have this opportunity for this challenge. great title, seems the lighting is a bit harsh - a little too bright and blown out in some areas - super idea though - it matches the challenge perfectly :)</td>', 'awww..this screams "education" to me - great idea - and how lucky for you to have this opportunity for this challenge. great title, seems the lighting is a bit harsh - a little too bright and blown out in some areas - super idea though - it matches the challenge perfectly :)', '2006-03-16 12:38:05.000000', NULL, 1),
(2233483, 304620, 44172, '<td valign="top">I really like this image, love the black and white and softness, nice expression on her face and chalkboard in background is great - I even like the slight slant it has - nice work :)</td>', 'I really like this image, love the black and white and softness, nice expression on her face and chalkboard in background is great - I even like the slight slant it has - nice work :)', '2006-03-16 12:39:08.000000', NULL, 1),
(2233488, 306551, 44172, '<td valign="top">LOL - great shot, like the busyness it has and I''m kinda glad you left it in color instead of switching it to black and white - though that would probably look real good as well. Calculus - ugh! nice job :)</td>', 'LOL - great shot, like the busyness it has and I''m kinda glad you left it in color instead of switching it to black and white - though that would probably look real good as well. Calculus - ugh! nice job :)', '2006-03-16 12:40:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2233494, 304602, 44172, '<td valign="top">Love the idea - but the green is rather distracting - I don''t think it enhances the image as much as you might expect, also seems to be a wee bit crooked - maybe a very slight rotate and my preference I think would have been for each beaker to be in focus as it appears the one in front has a softer focus.  Good idea and title though - meets the challenge well - good job :)</td>', 'Love the idea - but the green is rather distracting - I don''t think it enhances the image as much as you might expect, also seems to be a wee bit crooked - maybe a very slight rotate and my preference I think would have been for each beaker to be in focus as it appears the one in front has a softer focus.  Good idea and title though - meets the challenge well - good job :)', '2006-03-16 12:44:38.000000', NULL, 1),
(2233499, 306926, 44172, '<td valign="top">clever set up - rather pretty, my preference would have been to have less crop on the sides allowing some space past the ribbon ends and the lighting seems a wee bit much - blown out on pencil tips and especially front of erasers - a good studio idea though and certainly meets the challenge - good job :)</td>', 'clever set up - rather pretty, my preference would have been to have less crop on the sides allowing some space past the ribbon ends and the lighting seems a wee bit much - blown out on pencil tips and especially front of erasers - a good studio idea though and certainly meets the challenge - good job :)', '2006-03-16 12:47:27.000000', NULL, 1),
(2233539, 304967, 51385, '<td valign="top">How well I remember...nice shot.8.</td>', 'How well I remember...nice shot.8.', '2006-03-16 13:00:43.000000', NULL, 1),
(2233614, 304751, 50695, '<td valign="top">Your "light source" is casting a shadow... that shadow, and the reflection interfere with your illusion.</td>', 'Your "light source" is casting a shadow... that shadow, and the reflection interfere with your illusion.', '2006-03-16 13:34:12.000000', NULL, 1),
(2233622, 306510, 50695, '<td valign="top">I think I want this to be higher contrast. I want the children to "stand out" more.</td>', 'I think I want this to be higher contrast. I want the children to "stand out" more.', '2006-03-16 13:39:23.000000', NULL, 1),
(2233628, 306554, 50695, '<td valign="top">He''s not a dunce! He''s just a little grumpy and shy. awwwww (and he''s got great handwriting for a small breed!)</td>', 'He''s not a dunce! He''s just a little grumpy and shy. awwwww (and he''s got great handwriting for a small breed!)', '2006-03-16 13:42:18.000000', NULL, 1),
(2233632, 304603, 50695, '<td valign="top">I thought it was the pen vs. the sword... :)</td>', 'I thought it was the pen vs. the sword... :)', '2006-03-16 13:43:00.000000', NULL, 1),
(2233650, 306108, 55240, '<td valign="top">Interesting concept! 8 for ya!</td>', 'Interesting concept! 8 for ya!', '2006-03-16 13:47:55.000000', NULL, 1),
(2233672, 306836, 44172, '<td valign="top">LOL - cute idea - not sure if it meets the challenge that well - relying on title alone I think, not sure what is lying next to him, a little distracting - a thermometer? and I think his nose and face could have a bit sharper focus, crop seems a bit too tight - especially on the right - my preference would have been to see more space past his ears - funny though - great model :)</td>', 'LOL - cute idea - not sure if it meets the challenge that well - relying on title alone I think, not sure what is lying next to him, a little distracting - a thermometer? and I think his nose and face could have a bit sharper focus, crop seems a bit too tight - especially on the right - my preference would have been to see more space past his ears - funny though - great model :)', '2006-03-16 13:59:30.000000', NULL, 1),
(2233679, 305858, 44172, '<td valign="top">I rather like this image and the statement it makes. Nice work :)</td>', 'I rather like this image and the statement it makes. Nice work :)', '2006-03-16 14:06:01.000000', NULL, 1),
(2233684, 306289, 19831, '<td valign="top">hehehe :-), good humor factor in this shot! Good lighting and focus. I like the overall composition, might work well in a portrait crop too. Might be a little stronger if the book were not cut off in the framing at the bottom. Overall, good concept, interesting photo. Nice job.</td>', 'hehehe :-), good humor factor in this shot! Good lighting and focus. I like the overall composition, might work well in a portrait crop too. Might be a little stronger if the book were not cut off in the framing at the bottom. Overall, good concept, interesting photo. Nice job.', '2006-03-16 14:07:38.000000', NULL, 1),
(2233691, 306176, 44172, '<td valign="top">Not very interesting, perhaps a different perspective or maybe people in the shot, I wouldn''t know that this building has anything to do with education except for the title, it actually resembles our Dr''s office. Maybe if you included the sign saying "Carver Middle School." It''s in focus though and the lights have a good glow standing out against the rest of the natural light. :)</td>', 'Not very interesting, perhaps a different perspective or maybe people in the shot, I wouldn''t know that this building has anything to do with education except for the title, it actually resembles our Dr''s office. Maybe if you included the sign saying "Carver Middle School." It''s in focus though and the lights have a good glow standing out against the rest of the natural light. :)', '2006-03-16 14:11:21.000000', NULL, 1),
(2233693, 305797, 19831, '<td valign="top">hehehe, nice idea. The late night cram session :-) I like the dof you''ve used. The context of the shot is definitely there, but attention is drawn nicely to the watch, to get the concept of the image across. Might be a stronger presentation if the framing were cropped close to the bottom of the watch. It is hard to tell if that is a book or what the watch is sitting on, and feels like it doesn''t really add to the shot. Good lighting too, it does have the feel of late at night. Good job.</td>', 'hehehe, nice idea. The late night cram session :-) I like the dof you''ve used. The context of the shot is definitely there, but attention is drawn nicely to the watch, to get the concept of the image across. Might be a stronger presentation if the framing were cropped close to the bottom of the watch. It is hard to tell if that is a book or what the watch is sitting on, and feels like it doesn''t really add to the shot. Good lighting too, it does have the feel of late at night. Good job.', '2006-03-16 14:12:34.000000', NULL, 1),
(2233694, 306892, 19831, '<td valign="top">hehehe, hilarious :-) I love the expression on the guys face!</td>', 'hehehe, hilarious :-) I love the expression on the guys face!', '2006-03-16 14:13:26.000000', NULL, 1),
(2233696, 306570, 19831, '<td valign="top">Nice shot. Good scene, good composition. The whites seem almost blown on the bookshelves and desks, but I think it works with your processing. Great use of triangulation with your subjects. Good job :-)</td>', 'Nice shot. Good scene, good composition. The whites seem almost blown on the bookshelves and desks, but I think it works with your processing. Great use of triangulation with your subjects. Good job :-)', '2006-03-16 14:16:39.000000', NULL, 1),
(2233700, 306400, 44172, '<td valign="top">You can tell I''m getting old - I <i>used</i> to agree with this "expression" but now I know how important school really is. I guess I don''t care for the message but it meets the challenge and I really like the lighting from below and the perspective. Nice job :)</td>', 'You can tell I''m getting old - I used to agree with this "expression" but now I know how important school really is. I guess I don''t care for the message but it meets the challenge and I really like the lighting from below and the perspective. Nice job :)', '2006-03-16 14:19:36.000000', NULL, 1),
(2233703, 306624, 19831, '<td valign="top">A great concept here. Original and creative for the challenge I think. However, it took me a minute to see it. The boy seems easily missed in all that is going on in the shot. You may be suffering some low votes from speed voters that are not catching it. Perhaps a different angle could make him more prominent and strengthen this image. Focus and exposure are good. I really like the concept, just wish I could see a little more of the boy :-)</td>', 'A great concept here. Original and creative for the challenge I think. However, it took me a minute to see it. The boy seems easily missed in all that is going on in the shot. You may be suffering some low votes from speed voters that are not catching it. Perhaps a different angle could make him more prominent and strengthen this image. Focus and exposure are good. I really like the concept, just wish I could see a little more of the boy :-)', '2006-03-16 14:21:03.000000', NULL, 1),
(2233709, 305059, 44172, '<td valign="top">nice image - kind of small - but you can still make everything out. I like the green tone of coloring it has, the lighting on your main model seems a bit much - but I kind of like it as well as her expression :)</td>', 'nice image - kind of small - but you can still make everything out. I like the green tone of coloring it has, the lighting on your main model seems a bit much - but I kind of like it as well as her expression :)', '2006-03-16 14:22:19.000000', NULL, 1),
(2233737, 306950, 43565, '<td valign="top">I don''t get the connection to education.</td>', 'I don''t get the connection to education.', '2006-03-16 14:43:52.000000', NULL, 1),
(2233766, 306861, 43565, '<td valign="top">Good idea, but I think it would have been better to have the spines face the camera.</td>', 'Good idea, but I think it would have been better to have the spines face the camera.', '2006-03-16 14:56:22.000000', NULL, 1),
(2233772, 306311, 45790, '<td valign="top">Too centered and could be cropped tighter, but otherwise fine.</td>', 'Too centered and could be cropped tighter, but otherwise fine.', '2006-03-16 14:59:19.000000', NULL, 1),
(2233775, 306794, 45790, '<td valign="top">Very nice composition. Could use a little less exposure on the pencil.</td>', 'Very nice composition. Could use a little less exposure on the pencil.', '2006-03-16 15:00:36.000000', NULL, 1),
(2233779, 306153, 45790, '<td valign="top">Sorry but whenever I see a photo like this my first thought is "it is going to tumble over."</td>', 'Sorry but whenever I see a photo like this my first thought is "it is going to tumble over."', '2006-03-16 15:02:39.000000', NULL, 1),
(2233780, 306554, 45790, '<td valign="top">Very cute. Well done.</td>', 'Very cute. Well done.', '2006-03-16 15:03:29.000000', NULL, 1),
(2233787, 305674, 45790, '<td valign="top">Needs something that identifies it as a school and not jujst some random building. Seems oversharpened.</td>', 'Needs something that identifies it as a school and not jujst some random building. Seems oversharpened.', '2006-03-16 15:04:55.000000', NULL, 1),
