(2237528, 306269, 52472, '<td valign="top">It''s a bit too cluttered for my taste...</td>', 'It''s a bit too cluttered for my taste...', '2006-03-18 13:35:32.000000', NULL, 1),
(2237531, 306846, 43434, '<td valign="top">The picture needed straightening through a minor rotation.</td>', 'The picture needed straightening through a minor rotation.', '2006-03-18 13:36:35.000000', NULL, 1),
(2237532, 306414, 43434, '<td valign="top">LOL</td>', 'LOL', '2006-03-18 13:37:06.000000', NULL, 1),
(2237534, 306950, 43434, '<td valign="top">Interesting choice for education.  The picture on viewing is distracting for not being rotated to be straight - the candles add nothing to the picture - or the picture should be of the candles - I also can not figure out how a can of beer works for education - unless you are training people young on how to become an alcoholic.</td>', 'Interesting choice for education.  The picture on viewing is distracting for not being rotated to be straight - the candles add nothing to the picture - or the picture should be of the candles - I also can not figure out how a can of beer works for education - unless you are training people young on how to become an alcoholic.', '2006-03-18 13:39:37.000000', NULL, 1),
(2237538, 306755, 43434, '<td valign="top">You could have left untitled and it would have matched the image better ... in this picture the title is totally distracting.</td>', 'You could have left untitled and it would have matched the image better ... in this picture the title is totally distracting.', '2006-03-18 13:40:19.000000', NULL, 1),
(2237540, 306708, 43434, '<td valign="top">The is so out of focus it is distracting.</td>', 'The is so out of focus it is distracting.', '2006-03-18 13:41:00.000000', NULL, 1),
