(2237669, 306644, 53147, '<td valign="top">Nice pic - would have been better if you had cropped or rotated the pic so that it was square with the page.</td>', 'Nice pic - would have been better if you had cropped or rotated the pic so that it was square with the page.', '2006-03-18 15:33:49.000000', NULL, 1),
(2237673, 306110, 53147, '<td valign="top">My favorite of the school bus shots.</td>', 'My favorite of the school bus shots.', '2006-03-18 15:38:37.000000', NULL, 1),
(2237694, 304593, 53147, '<td valign="top">This was in our top 4. Love the shot and really like the use of red. And the fact that not a single one of them is looking at the teacher makes it hilarious. Beautiful pic. 9.</td>', 'This was in our top 4. Love the shot and really like the use of red. And the fact that not a single one of them is looking at the teacher makes it hilarious. Beautiful pic. 9.', '2006-03-18 15:59:18.000000', NULL, 1),
(2237696, 306861, 53147, '<td valign="top">Clean and crisp. I really like that you used this side of the books rather than the binding. The thin lines of color compliment the apples really well. This was in our top 4. 9</td>', 'Clean and crisp. I really like that you used this side of the books rather than the binding. The thin lines of color compliment the apples really well. This was in our top 4. 9', '2006-03-18 16:00:11.000000', NULL, 1),
(2237698, 306489, 53147, '<td valign="top">Beautiful shot. 9</td>', 'Beautiful shot. 9', '2006-03-18 16:00:45.000000', NULL, 1),
(2237700, 306325, 53147, '<td valign="top">We really liked this one. I don''t think it would have been the same without the woman in the red shirt walking through. 9</td>', 'We really liked this one. I don''t think it would have been the same without the woman in the red shirt walking through. 9', '2006-03-18 16:01:18.000000', NULL, 1),
(2237876, 306462, 48968, '<td valign="top">Witty, creative, and nicely shot.</td>', 'Witty, creative, and nicely shot.', '2006-03-18 17:55:47.000000', NULL, 1),
