INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2684284, 304549, 12448, '<td valign="top">Greetings from me!<br/> <br/>Hi, I see you never received the critique you requested on your picture so here goes. ;)<br/> <br/>I see a lot of the comments ask what this had to do with education and honestly I had to ask the same thing.  So for the sake of the picture, I''m betting you got a lot of Does Not Meet The Challenge votes.  Now if this had been for the footwear challenge, your score might have gone up quite a bit.<br/> <br/>So I''m going just comment on the shot itself.  Those look like very comfortable slippers, the way the backs are pushed down tell me they are used usually in a hurry and probably for only short periods of time.  Judging from the floor their are on and the stains and markings I''m guessing mostly in the garage or outdoor patio area.<br/> <br/>The picture has potential overall but a few things got to me right off. First all the negative space, it seems really top heavy and the darker cement is more a distraction than an asset to me personally.  It could work for you if you came from a different angle, taking the corner of the dark area inside and either pinpointing it in the center top, using it like a type of shading or border.  Then you could re-arrange the shoes in differnt patterns and play with the overall composition.  Remember that things don''t always have to be centered as long as they are still balanced to a point, the rule of thirds is a wonderful thing, you could set up a slipper up on the upper and lower part of that.<br/> <br/>Don''t be afraid to experiement and play with a shot when shooting it.  It''s amazing some of the stuff that will pop out at you when you least expect it.  That''s the best thing about digital is you can''t waste film! :)<br/> <br/>Your lighting also comes off just a bit dull, a slight levels or curves adjustment could fix that.<br/> <br/>Again, the potential is there, looking at your profile, don''t quit trying!<br/> <br/>I hope my comments help and Good Luck in future Challenges!<br/> <br/>Deannda</td>', 'Greetings from me! Hi, I see you never received the critique you requested on your picture so here goes. ;) I see a lot of the comments ask what this had to do with education and honestly I had to ask the same thing.  So for the sake of the picture, I''m betting you got a lot of Does Not Meet The Challenge votes.  Now if this had been for the footwear challenge, your score might have gone up quite a bit. So I''m going just comment on the shot itself.  Those look like very comfortable slippers, the way the backs are pushed down tell me they are used usually in a hurry and probably for only short periods of time.  Judging from the floor their are on and the stains and markings I''m guessing mostly in the garage or outdoor patio area. The picture has potential overall but a few things got to me right off. First all the negative space, it seems really top heavy and the darker cement is more a distraction than an asset to me personally.  It could work for you if you came from a different angle, taking the corner of the dark area inside and either pinpointing it in the center top, using it like a type of shading or border.  Then you could re-arrange the shoes in differnt patterns and play with the overall composition.  Remember that things don''t always have to be centered as long as they are still balanced to a point, the rule of thirds is a wonderful thing, you could set up a slipper up on the upper and lower part of that. Don''t be afraid to experiement and play with a shot when shooting it.  It''s amazing some of the stuff that will pop out at you when you least expect it.  That''s the best thing about digital is you can''t waste film! :) Your lighting also comes off just a bit dull, a slight levels or curves adjustment could fix that. Again, the potential is there, looking at your profile, don''t quit trying! I hope my comments help and Good Luck in future Challenges! Deannda', '2006-08-01 16:37:37.000000', NULL, 0),
